CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','viewer') NOT NULL, session_version INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE login_limits (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL, started BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE patients (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, sex ENUM('male','female','other') NOT NULL, birth_date DATE NOT NULL, notes TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE readings (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, patient_id INT NOT NULL, kind ENUM('bp','glucose') NOT NULL, measured_at DATETIME NOT NULL, slot ENUM('morning','evening','other') NOT NULL, group_uuid CHAR(36) NULL, systolic SMALLINT NULL, diastolic SMALLINT NULL, pulse SMALLINT NULL, glucose DECIMAL(6,1) NULL, context VARCHAR(30) NULL, fasting_hours DECIMAL(4,1) NULL, meal_at DATETIME NULL, notes TEXT NOT NULL, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, voided_at DATETIME NULL, void_reason VARCHAR(500) NULL, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX(patient_id,measured_at), INDEX(group_uuid)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, action VARCHAR(40) NOT NULL, entity_id BIGINT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
